pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
    let delay = self.base_delay_ms.min(self.max_delay_ms);
    if delay == 0 || delay == self.max_delay_ms {
        return delay;
    }

    // Once the shift exceeds u64, any positive delay has reached the cap.
    if retry_index >= u64::BITS {
        return self.max_delay_ms;
    }

    delay
        .saturating_mul(1u64 << retry_index)
        .min(self.max_delay_ms)
}

